import itertools
import torch

def filt(x):
    return x < 10

@torch.compile(backend="eager", fullgraph=True)
def f(x):
    x = x + 1
    return zip(range(3), filter(filt, itertools.count()))

# comment out to continue
f(torch.ones(3))

@torch.compile(backend="eager")
def g(x):
    x = x + 1
    return filter(filt, [1, 2, 3])

print(type(g(torch.ones(3))))
assert isinstance(g(torch.ones(3)), filter)
filter should support infinite iterators and should return a filter type, similar to how dynamo handles map and zip.
